import{api}from'./api.js';import{escapeHtml,handleAdminError,loading,openLegacyModal}from'./shell.js?v=20260913-7';import{mountLegacyPage}from'./legacy-page.js?v=20260905-2';
const root=mountLegacyPage('bundles','Add Bundles','Bundles');let tab=new URLSearchParams(location.search).get('tab')||'data',data;
async function load(){try{data=await api(`/admin/bundles?tab=${encodeURIComponent(tab)}`);tab=data.tab;render()}catch(e){handleAdminError(e)}}
function label(k){return data.config.fields[k]?.label||k.replaceAll('_',' ')}function money(k,v){return ['price','smart','top','affiliate','reseller','api'].includes(k)&&v!==''?`₦${Number(v).toLocaleString(undefined,{minimumFractionDigits:2})}`:escapeHtml(v)}
function render(){const plans=data.plans?.data||[];root.innerHTML=`<div class="card"><div class="card-header"><div class="d-flex align-items-center flex-wrap old-tab-buttons" style="gap:10px"><h4 class="card-title mr-auto">${data.config.title}</h4><button class="btn btn-primary btn-sm" id="add"><i class="fa fa-plus"></i> Add New Plan</button>${Object.entries(data.tabs).map(([k,v])=>`<a class="btn btn-${k===tab?'primary':'light'} btn-sm" href="/admin/bundles/?tab=${k}">${v.label}</a>`).join('')}</div></div><div class="card-body"><div class="table-responsive"><table class="table table-striped table-hover"><thead><tr><th>#</th>${data.config.display.map(k=>`<th>${label(k)}</th>`).join('')}<th>Action</th></tr></thead><tbody>${plans.length?plans.map((p,i)=>`<tr><td>${i+1}.</td>${data.config.display.map(k=>`<td>${money(k,p[k]??'')}</td>`).join('')}<td><button class="btn btn-link btn-info btn-lg" data-edit="${i}" title="Edit"><i class="fa fa-edit"></i></button><button class="btn btn-link btn-danger btn-lg" data-delete="${escapeHtml(p[data.config.primary])}" title="Delete"><i class="fas fa-trash-alt"></i></button></td></tr>`).join(''):`<tr><td colspan="${data.config.display.length+2}" class="text-center py-4"><b>No plans added yet</b></td></tr>`}</tbody></table></div></div></div>`;document.querySelector('#add').onclick=()=>modal();document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>modal(plans[Number(b.dataset.edit)]));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>remove(b.dataset.delete))}
function field(name,meta,value=''){if(meta.type==='select')return `<div class="form-group"><label>${meta.label}</label><select class="form-control" name="${name}" ${meta.required===false?'':'required'}>${meta.options.map(o=>`<option ${String(value)===String(o)?'selected':''}>${o}</option>`).join('')}</select></div>`;return `<div class="form-group"><label>${meta.label}</label><input class="form-control" name="${name}" type="${meta.type||'text'}" value="${escapeHtml(value)}" ${meta.type==='number'?'min="0" step="0.01"':''} ${meta.required===false?'':'required'}></div>`}
function modal(plan=null){openLegacyModal({title:`${plan?'Edit':'Add New'} ${data.config.label}`,body:`<form id="bundle-form">${Object.entries(data.config.fields).map(([k,m])=>field(k,m,plan?.[k]??'')).join('')}</form>`,confirmText:plan?'Update Plan':'Save Plan',onConfirm:async(host,close)=>{const form=host.querySelector('#bundle-form');if(!form.reportValidity())return;loading();try{const id=plan?.[data.config.primary],out=await api(`/admin/bundles/${tab}${id?`/${id}`:''}`,{method:id?'PATCH':'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});close();await Swal.fire(out.title||'Successful',out.message||'Plan saved.','success');load()}catch(e){handleAdminError(e)}}})}
async function remove(id){const c=await Swal.fire({icon:'warning',title:'Delete this plan?',text:'This action cannot be undone.',showCancelButton:true,confirmButtonText:'Delete',confirmButtonColor:'#f25961'});if(!c.isConfirmed)return;loading('Deleting…');try{const out=await api(`/admin/bundles/${tab}/${id}`,{method:'DELETE'});await Swal.fire(out.title||'Deleted',out.message||'Plan deleted.','success');load()}catch(e){handleAdminError(e)}}load();
